def wheel(cx):
    d.add(f'<circle cx="{cx:.1f}" cy="{ey(WHEEL_Y):.1f}" r="{WHEEL_R * K:.1f}" fill="#1b1f25" stroke="#4d5560" stroke-width="2"/>')
    d.add(f'<circle cx="{cx:.1f}" cy="{ey(WHEEL_Y):.1f}" r="5" fill="#6d7681"/>')


# Bogies first (the elevation's bogie outlines, frame and wheels), so the body skirt overlaps them as on the train.
for b in (BOGIE_CAB, BOGIE_REAR):
    d.add(f'<path d="{epath(b)}" fill="#2a2f36" stroke="#3f464f" stroke-width="1.2"/>')
d.add(f'<path d="{epath(MI2_BOGIE, ex2)}" fill="#2a2f36" stroke="#3f464f" stroke-width="1.2"/>')
for a in AXLES:
    wheel(ex(a))
wheel(ex2(1575.2))
# The bogie frames over the wheels (the elevation's frame outlines, closed).
for p in FRAMES:
    d.add(f'<path d="{epath(p)}Z" fill="#2a2f36" stroke="#3f464f" stroke-width="1"/>')
d.add(f'<path d="{epath(MI2_FRAME, ex2)}Z" fill="#2a2f36" stroke="#3f464f" stroke-width="1"/>')

# MI2, the end next to the cab car.
d.clip('c2', epath(MI2_BODY, ex2))
d.group('c2')
X0 = d.VB_X - 10
