d.add(f'<rect x="{g0:.1f}" y="{ey(195.6):.1f}" width="{g1 - g0:.1f}" height="{ey(381.1) - ey(195.6):.1f}" fill="#2b3037"/>')
for i in range(1, 6):
    xi = g0 + i * (g1 - g0) / 6
    d.add(f'<line x1="{xi:.1f}" y1="{ey(197):.1f}" x2="{xi:.1f}" y2="{ey(379.5):.1f}" stroke="#41474f" stroke-width="1.5"/>')

# MC2, the cab car.
d.clip('c1', epath(BODY))
d.group('c1')
d.add(f'<rect x="{REAR - 2:.1f}" y="{ROOF - 10}" width="{TIP - REAR + 14:.1f}" height="{d.H + 20}" fill="url(#body)"/>')
# Unpainted: a roof strip down to the roof/side line behind the cab joint, and that line.
d.add(f'<rect x="{REAR - 2:.1f}" y="{ROOF - 10}" width="{ex(CAB_JOINT) - REAR + 2:.1f}" height="{ey(ROOF_SEAM) - ROOF + 10:.1f}" fill="url(#roof)"/>', 'plain')
