d.end()
# Seams and panels: cab joint, nose panels, the plate on the cab side, the two small lamps under the windows.
for p in LINES:
    d.add(f'<path d="{epath(p)}" fill="none" stroke="#000" stroke-opacity="0.2" stroke-width="1.2"/>')
d.add(f'<path d="{epath(NOSE_PANEL)}" fill="none" stroke="#000" stroke-opacity="0.2" stroke-width="1.2"/>')
for p in SKIRT_LINES:
    d.add(f'<path d="{epath(p)}" fill="none" stroke="#000" stroke-opacity="0.12" stroke-width="1"/>')
# Roof: the hatch boxes over the cab and the equipment cover at the rear end.
