for p in ROOF_LINES:
    d.add(f'<path d="{epath(p)}" fill="none" stroke="#8a929b" stroke-width="0.8"/>')
# Windows, the narrow windows by the doors, the doors.
for x0, x1 in WINDOWS:
    d.windows(ex(x0), ex(x1), 1, f(WIN_Y[0]), f(WIN_Y[1]))
for p in (SLIT_A, SLIT_B, SLIT_C, SLIT_D):
    d.add(f'<path d="{epath(p)}" fill="#0b0d10"/>')
for ring, door, win in ((DOOR_RING_A, DOOR_A, DOOR_A_WIN), (DOOR_RING_B, DOOR_B, DOOR_B_WIN)):
    d.paint(f'<path d="{epath(door)}" fill="url(#ftdark)"/>', FT)
    d.paint(f'<path d="{epath(ring)}" fill="{ORANGE_C}"/>', FT)
    d.add(f'<path d="{epath(door)}" fill="none" stroke="#8d949c" stroke-width="1.6"/>', 'plain')
    d.add(f'<path d="{epath(win)}" fill="url(#glass)" stroke="#0b0d10" stroke-width="2"/>')
# Cab side window.
d.add(f'<path d="{epath(CAB_WIN_FRAME)}" fill="#0b0d10"/>')
d.add(f'<path d="{epath(CAB_WIN_GLASS)}" fill="url(#glass)"/>')
d.end()

# Door steps and the plough under the nose.
for p in STEPS:
    d.add(f'<path d="{epath(p)}" fill="#3a4450"/>')
d.add(f'<path d="{epath(PLOUGH)}" fill="#3b4148"/>')

COMMENT = '// Flytoget Type 78 (CAF Oaris, cab car MC2), side view to scale. Generated by scripts/trains/flytoget78.py (sources and measurements there); docs/TRAIN_ART.md.'
OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'apps', 'web', 'src', 'components', 'trains', 'Flytoget78.tsx')
if __name__ == '__main__':
    main(d, 'Flytoget78Side', COMMENT, OUT)
